// Demo prospects so the workflow runs with zero Google setup.
const cfg = $('Campaign Config').first().json;
const rows = Array.isArray(cfg.testRows) ? cfg.testRows : [];
if (!rows.length) throw new Error('useTestRows is true but Campaign Config.testRows is empty');
return rows.map((r) => ({ json: { ...r, row_number: null } }));

// Name hygiene: normalize what can be trusted, route everything else to the
// pre-recorded fallback intro. The safe failure mode is a generic greeting -
// never a mangled name in a cloned voice.
const cfg = $('Campaign Config').first().json;
const TITLES = /^(mr|mrs|ms|miss|dr|prof|sir|madam|mx)\.?\s+/i;
const BLOCK = new Set(['test','testing','unknown','n/a','na','none','null','user','admin','info','sales','support','hello','hi','friend','sir','madam','team','contact','lead']);

const pick = (row, keys) => {
  for (const k of keys) if (row[k] != null && String(row[k]).trim() !== '') return String(row[k]);
  return '';
};

let rows = $input.all().map((i) => i.json);
const limit = Number(cfg.rowLimit) || 0;
if (limit > 0) rows = rows.slice(0, limit);
if (!rows.length) throw new Error('No prospect rows found');

return rows.map((row) => {
  const rawName = pick(row, ['first_name', 'firstName', 'FirstName', 'First Name', 'name', 'Name']);
  const rawCompany = pick(row, ['company', 'Company', 'company_name', 'Company Name', 'org', 'Organization']);
  const company = rawCompany.replace(/[<>&]/g, '').replace(/\s+/g, ' ').trim().slice(0, 40);

  let s = rawName.normalize('NFKC').trim().replace(TITLES, '');
  s = s.replace(/[^\p{L}\p{M}\s'\u2019-]/gu, ' ');   // drop emoji, digits, punctuation
  s = s.replace(/\s+/g, ' ').trim().split(' ')[0];      // first token only

  let valid = /^\p{L}[\p{L}\p{M}'\u2019-]{1,19}$/u.test(s) && /[aeiouy\u00e0-\u00ff]/i.test(s) && !BLOCK.has(s.toLowerCase());
  if (valid) {
    s = s[0].toUpperCase() + s.slice(1).toLowerCase();
    s = s.replace(/(['\u2019-])(\p{L})/gu, (m, p, c) => p + c.toUpperCase());
  }

  const greeting = String(cfg.greetingTemplate || 'Hi {name}!').split('{name}').join(s);
  let useFallback = !valid;
  let reason = valid ? '' : `name "${rawName}" failed hygiene`;
  if (valid && greeting.length > (Number(cfg.maxGreetingChars) || 90)) {
    useFallback = true;
    reason = 'greeting too long';
  }
  if (cfg.dryRun) {
    useFallback = true;
    reason = reason || 'dry run (no WaveSpeed spend)';
  }

  const firstName = valid ? s : 'friend';
  const chipLabel = useFallback && !valid
    ? (company ? `Hey there \u00b7 ${company}` : 'Hey there')
    : (company ? `${firstName} \u00b7 ${company}` : firstName);

  return { json: {
    row_number: row.row_number != null ? row.row_number : null,
    firstName,
    company,
    chipLabel,
    greeting,
    useFallback,
    fallbackReason: reason,
  } };
});

// Fail loudly on failed TTS jobs; stop the poll loop at the timeout.
const cfg = $('Campaign Config').first().json;
for (const item of $input.all()) {
  const d = item.json.data || {};
  if (d.status === 'failed') {
    throw new Error('WaveSpeed TTS failed: ' + (d.error || 'no reason given'));
  }
}
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 30) * 60) / 3);
if ($runIndex + 1 >= maxPolls) {
  throw new Error('TTS did not finish within ' + cfg.timeoutMinutes + ' minutes.');
}
return $input.all();

// Fail loudly on failed lip-sync jobs; stop the poll loop at the timeout.
const cfg = $('Campaign Config').first().json;
for (const item of $input.all()) {
  const d = item.json.data || {};
  if (d.status === 'failed') {
    throw new Error('WaveSpeed lipsync failed: ' + (d.error || 'no reason given'));
  }
}
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 30) * 60) / Math.max(2, Number(cfg.pollSeconds || 6)));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Lip-sync did not finish within ' + cfg.timeoutMinutes + ' minutes.');
}
return $input.all();

// Two scenes, hard cut. duration -1 = the renderer probes each clip and sizes
// the scene to it, so variable-length intros need no bookkeeping. The body
// scene gets a slow 1.05x push-in (zoom) so the cut reads as a deliberate
// edit. Optional music bed spans both scenes; keep audio items to src+volume.
const cfg = $('Campaign Config').first().json;
const rows = $input.all().map((i) => i.json);
if (!rows.length) throw new Error('No prospects to render');
for (const k of ['introMasterUrl', 'bodyVideoUrl', 'fallbackIntroUrl']) {
  if (!/^https:\/\/\S+$/.test(String(cfg[k] || '')) || String(cfg[k]).includes('YOUR-CDN')) {
    throw new Error(`Campaign Config.${k} is not set - upload the clip and paste its public https URL`);
  }
}

const W = Number(cfg.videoWidth) || 1920;
const H = Number(cfg.videoHeight) || 1080;
const cx = Math.round(W / 2);
const cy = Math.round(H / 2);

const chip = {
  type: 'TEXT',
  x: Math.round(W * 0.05),
  y: Math.round(H * 0.88),
  anchor: 'center-left',
  track: 1,
  enterBegin: 0.5,
  enterEnd: 1,
  enterAnimation: 'fade',
  style: { fontFamily: 'Archivo' },
  html: `<div style='display:inline-block; background:rgba(10,10,10,0.62); border-left:6px solid ${cfg.brandColor || '#C6FF3D'}; border-radius:12px; padding:16px 28px; color:#ffffff; font-size:${Math.round(H * 0.028)}px; font-weight:700; letter-spacing:0.5px;'>{{chipLabel}}</div>`,
};

const payload = {
  name: 'avatar-outreach',
  width: W,
  height: H,
  frameRate: 30,
  backgroundColor: '#000000',
  outputFormat: 'mp4',
  variables: { introUrl: cfg.fallbackIntroUrl, chipLabel: 'Hey there' },
  scenes: [
    {
      id: 'intro',
      duration: -1,
      backgroundColor: '#000000',
      visuals: [
        { type: 'VIDEO', id: 'introclip', src: '{{introUrl}}', x: cx, y: cy, width: W, height: H, anchor: 'center-center', volume: 1, track: 0 },
        ...(cfg.nameChip ? [chip] : []),
      ],
    },
    {
      id: 'body',
      duration: -1,
      backgroundColor: '#000000',
      visuals: [
        { type: 'VIDEO', id: 'bodyclip', src: cfg.bodyVideoUrl, x: cx, y: cy, width: W, height: H, anchor: 'center-center', volume: 1, track: 0, zoom: { depth: 1.05 } },
      ],
    },
  ],
};
if (cfg.musicUrl) {
  payload.audios = [{ src: cfg.musicUrl, volume: Number(cfg.musicVolume) || 0.08 }];
}

return [{ json: { payload, rows } }];

// One bulk item per prospect. Job names are slugged: spaces in output names
// produce CDN URLs that need percent-encoding everywhere downstream.
const cfg = $('Campaign Config').first().json;
const rows = $json.rows;
const slug = (v) => String(v).toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
return rows.map((r, i) => {
  if (!/^https:\/\/\S+$/.test(String(r.introUrl || ''))) {
    throw new Error(`Row ${i + 1} (${r.firstName}): missing intro URL (${r.introSource || 'unknown'})`);
  }
  return { json: {
    row_number: r.row_number,
    firstName: r.firstName,
    introSource: r.introSource,
    fallbackReason: r.fallbackReason || '',
    name: slug(`${cfg.batchName}-${r.firstName}-r${r.row_number != null ? r.row_number : i + 1}`),
    variables: { introUrl: r.introUrl, chipLabel: r.chipLabel },
  } };
});

// The free validate endpoint runs the exact pipeline a render runs, so a
// failure here is a payload/URL bug - surface every failing row at once.
const built = $('Build bulk items').all();
const failures = [];
const out = [];
$input.all().forEach((res, i) => {
  const status = res.json.statusCode;
  const body = res.json.body || {};
  const meta = built[i].json;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => `${d.field}: ${d.message}`).join('; ')
      : JSON.stringify(body).slice(0, 300);
    failures.push(`- ${meta.firstName} (${meta.introSource}): HTTP ${status} ${body.message || body.error || ''} ${details}`);
    return;
  }
  out.push({ json: { ...meta, creditsRequired: body.creditsRequired || 0 }, pairedItem: { item: i } });
});
if (failures.length) {
  throw new Error(`Zvid rejected ${failures.length} row(s):\n${failures.join('\n')}`);
}
return out;

const items = $input.all().map((i) => i.json);
const total = items.reduce((s, x) => s + (x.creditsRequired || 0), 0);
return [{ json: {
  dryRun: true,
  rows: items.length,
  creditsRequired: total,
  perRow: items.map((x) => ({ name: x.name, firstName: x.firstName, introSource: x.introSource, credits: x.creditsRequired })),
  note: 'Free pass: every intro used the fallback clip, so WaveSpeed spent $0 and Zvid only validated + quoted credits. Set dryRun: false to lip-sync and render for real.',
} }];

const cfg = $('Campaign Config').first().json;
const items = $input.all().map((i) => i.json);
const slug = (v) => String(v).toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
return [{ json: {
  request: {
    payload: $('Compose template payload').first().json.payload,
    items: items.map(({ name, variables }) => ({ name, variables })),
    name: slug(cfg.batchName) || 'avatar-outreach',
  },
  rowsMeta: items.map(({ row_number, firstName, introSource, fallbackReason, name }) => ({ row_number, firstName, introSource, fallbackReason, name })),
} }];

// Map every queued job back to its prospect via jobs[].index (job name is
// null until completed, so never join by name).
const meta = $('Build bulk request').first().json.rowsMeta;
const s = $input.first().json;
if (!s || !s.bulkId) {
  throw new Error('Bulk submit did not return a bulkId: ' + JSON.stringify(s).slice(0, 300));
}
const jobsMeta = (s.jobs || []).map((j) => ({ jobId: j.jobId, ...(meta[j.index] || {}) }));
const rejected = (s.errors || []).map((e) => {
  const idx = e.item != null ? e.item : e.index;
  return { ...(meta[idx] || {}), status: 'rejected', error: typeof e.error === 'string' ? e.error : (e.error && e.error.message) || e.message || 'rejected at submit' };
});
return [{ json: { bulkId: s.bulkId, jobsMeta, rejected, creditsReserved: s.creditsReserved } }];

// Loop back to the wait node unless we have polled past timeoutMinutes.
const cfg = $('Campaign Config').first().json;
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 30) * 60) / Math.max(2, Number(cfg.pollSeconds || 6)));
const first = $input.first().json;
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Timed out after ${cfg.timeoutMinutes} min with ${first.bulk.counts.pending} job(s) still rendering. Check later: GET ${cfg.apiUrl}/api/render/bulk/${$('Collect submission').first().json.bulkId}`);
}
return [{ json: { bulkId: $('Collect submission').first().json.bulkId } }];

const cs = $('Collect submission').first().json;
const byId = new Map(cs.jobsMeta.map((m) => [m.jobId, m]));
const resp = $input.first().json;
const out = [];
for (const job of resp.jobs || []) {
  const m = byId.get(job.id) || {};
  out.push({ json: {
    row_number: m.row_number != null ? m.row_number : null,
    firstName: m.firstName || job.name || job.id,
    introSource: m.introSource || '',
    fallbackReason: m.fallbackReason || '',
    status: job.status,
    video_url: job.outputUrl || '',
    thumbnail_url: job.thumbnailUrl || '',
    creditsCharged: job.creditsConsumed != null ? job.creditsConsumed : job.creditsEstimated,
    error: job.errorMessage || '',
  } });
}
for (const r of cs.rejected || []) {
  out.push({ json: { ...r, video_url: '', thumbnail_url: '', creditsCharged: 0 } });
}
if (!out.length) throw new Error('Bulk status returned no jobs');
return out;

const cfg = $('Campaign Config').first().json;
const rows = $('Build results').all().map((i) => i.json);
const cs = $('Collect submission').first().json;
const done = rows.filter((r) => r.status === 'completed');
const problems = rows.filter((r) => r.status !== 'completed');
return [{ json: {
  rendered: done.length,
  problems: problems.length,
  lipsyncIntros: rows.filter((r) => r.introSource === 'lipsync').length,
  fallbackIntros: rows.filter((r) => r.introSource === 'fallback').length,
  creditsReserved: cs.creditsReserved,
  bulkId: cs.bulkId,
  videos: done.map((r) => ({ name: r.firstName, url: r.video_url })),
  failures: problems,
  note: cfg.useTestRows
    ? 'useTestRows: true - nothing was written back. Point sheetUrl at your prospect sheet and set useTestRows: false for real campaigns.'
    : 'Status / VideoUrl / IntroSource written back to the sheet.',
} }];
